using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CorruptedEclipseCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Enemy/CorruptedEclipseCustomDescription", order = 0)]
public class CorruptedEclipseCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		EvenOddSoulHeatAction obj = battleAction as EvenOddSoulHeatAction;
		string actionDescription = obj.EvenAction.GetActionDescription(GetAmountWithoutEquation(amountModified));
		string actionDescription2 = obj.OddAction.GetActionDescription(GetAmountWithoutEquation(amountModified));
		return Smart.Format(GetRawLocalizedDescription(battleAction), actionDescription, actionDescription2);
	}
}
